const kebab = (s: string) => s.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);

/** CSS custom properties for both themes (themes switch with [data-theme] or the OS setting). */
export function tokensCss(): string {
  const vars = (o: Record<string, string>, prefix: string) => Object.entries(o).map(([k, v]) => `  --${prefix}${kebab(k)}: ${v};`).join('\n');
  const base = [
    `  --font-sans: ${tokens.font.sans};`,
    `  --font-mono: ${tokens.font.mono};`,
    vars(tokens.font.size, 'text-'),
    vars(tokens.font.lineHeight, 'leading-'),
    vars(Object.fromEntries(Object.entries(tokens.space).map(([k, v]) => [String(k), v])), 'space-'),
    vars(tokens.radius, 'radius-'),
    vars(tokens.motion, 'motion-'),
    vars(tokens.layout, 'layout-'),
  ].join('\n');
  return `/* Generated from ui/src/tokens.ts. Do not edit. */
:root {\n${base}\n${vars(tokens.theme.dark, 'c-')}\n  color-scheme: dark;\n}
@media (prefers-color-scheme: light) {\n  :root:not([data-theme="dark"]) {\n${vars(tokens.theme.light, 'c-')}\n    color-scheme: light;\n  }\n}
:root[data-theme="light"] {\n${vars(tokens.theme.light, 'c-')}\n  color-scheme: light;\n}
:root[data-theme="dark"] {\n${vars(tokens.theme.dark, 'c-')}\n  color-scheme: dark;\n}
`;
}
